import re
import time
from six import StringIO
from past.builtins import basestring
import os
import subprocess
from robot.api import logger
from ta_tshark_hex_parser.hex_parser import HexParser
from ta_pdml_parser.asnParser import ConvertAsnToPythonStructure
from ta_tshark_hex_parser.parser_exceptions import UesimConverterError, AsnParserError
from ute_common_abstract_core.message import Message
from ute_common_abstract_core.message import MessageField
from ta_tshark_hex_parser.lua_dissector.message_type_mapping import physical_channel_message_type_mapping, rrc_type_mapping
from ta_tshark_hex_parser.msg_type_to_msg_name_from_hex import protocol_mapping
from ta_tshark_hex_parser.hex_source import RRCHexSourceDescription, NRRRCHexSourceDescription

RAISE_ON_MSG_TYPE_DECODE_FAILED = True

USE_PAYLOAD_FIX = True      # temporary fix until IPHY resolves some JIRAs

DEFAULT_SOURCE = RRCHexSourceDescription(line_template=r'0x(\S+\s+\S+)', separator=r"\s+",
                                         column_descripions=['type', 'hex'], sample_line='0x0042    00555555550000')

DEFAULT_SOURCE_5G = NRRRCHexSourceDescription(line_template=r'(0x\S+\s+0x\S+\s+\S+)', separator=r"\s+",
                                              column_descripions=['protocol', 'type', 'hex'],
                                              sample_line='0x3433    0x0042    00555555550000')

FORCED_PROTOCOL = None


def enforce_rrc_protocol(protocol_name):
    """
    Enforces specific protocol in case source is producing single rrc protocol messages but in unreliable way.
    This is temp WA for Airphone in SA mode.
    :param protocol_name:
    """
    protocol_name = str(protocol_name)
    av_protocols = list(rrc_type_mapping.values())
    assert protocol_name in av_protocols,\
        "Protocol: {} not in available protocols: {}".format(protocol_name, av_protocols)
    global FORCED_PROTOCOL
    FORCED_PROTOCOL = protocol_name


class UesimParser(HexParser):
    """
    Class used to parse message types and their hex representation from tshark output with option -E fields.
    Tshark output with specified column could be determined with HexSourceDescription class.
    In HexSourceDescription 2 columns are mandatory - message type and hex value. The order in column_descriptions parameter
    must match tshark -e field_name order of columns.
    Default RRCHexSourceDescription provided above consists of columns: type, hex and corresponding tshark command
     must be invoked with parameters:
      ./tshark -T fields -e iphy.message.type -e iphy.data
    """

    def __init__(self, stop_condition=None, source_description=DEFAULT_SOURCE,
                 source_output_substitutes=[(':', '')]):
        """
        :param stop_condition:
        :param source_description: subclass of HexSourceDescription class object
        :param source_output_substitutes: list of tuples, default substitute is applied to hex value in tshark output,
        changes 00:11 to 0011
        """
        self.source_description = source_description
        self.source_separator = self.source_description.source_separator
        self.source_output_substitutes = source_output_substitutes
        self.uesim_dump_path = os.environ.get('UESIM_DUMP_PATH', '/opt/emssim/util/uesim-dump')
        self.protocols_parsed_separately = ['m3ap', 's1ap', 'iphy', 'x2ap', 'lte_rrc', 'nr-rrc']
        self.uesim_dump_supported_protocols = ['m3ap', 's1ap', 'x2ap', 'rrc', 'nas', '1x', 'hrpd', 'rrc5g']
        self.message_type_mapping = self._convert_lua_mapping_to_uesim_mapping(physical_channel_message_type_mapping)
        self._default_stop_condition = lambda: 9999
        self.stop_condition = stop_condition if stop_condition is not None else self._default_stop_condition
        self._sleep_between_chunks = 0.01

    class UesimHexMsg(object):
        """Internal class for Uesim hex message."""

        def __init__(self, protocol, pdu_type, hex):
            """

            :param protocol:
            :param pdu_type:
            :param hex:
            """
            self.protocol = protocol
            self.pdu_type = pdu_type
            self.hex = hex

        def __str__(self):
            name = self.__class__.__name__
            return '%s(%s : %s)' % (name, self.pdu_type, self.hex)

        def dump_for_uesim(self):
            """

            :return:
            :rtype: str
            """
            return '@dump %s %s %s' % (self.protocol, self.pdu_type, self.hex)

    def _convert_lua_mapping_to_uesim_mapping(self, mapping):
        """
        Function used to convert message name mapping taken from iphy_packet.lua file to uesim-dump message naming (some word revert and word
        removal can be applied).
        :param mapping: dict e.g. {1: 'NAME'}
        :return:  dict e.g. {1:'ANOTHER_NAME'}
        """
        uesim_mapping = {}
        not_remove_preffix = ['CCCH', 'DCCH', 'SCH', 'MCCH-R17', 'SCCH', 'SBCCH']
        change_order = ['SCH']
        change_order_last_two_words = ['NB', 'BR', 'R17']

        for (m_id, m_name) in list(mapping.items()):
            add_hyphen_plus_suffix = str(re.sub('_', '-', m_name)).upper() + '-Message'
            name = self._remove_prefix(add_hyphen_plus_suffix, not_remove_preffix)
            name = self._change_order(name, change_order)
            name = self._change_order_last_two_words(name, change_order_last_two_words)
            uesim_mapping[m_id] = name
        # pprint.pprint(uesim_mapping)
        return uesim_mapping

    def _convert_rrc_type_to_uesim_rrc_type(self, rrc_type):
        uesim_rrc_mapping = {'rrc': 'rrc',
                             'nr-rrc': 'rrc5g'}
        assert rrc_type in list(uesim_rrc_mapping.keys()), \
            'rrc type: {} not in list of supported: {}'.format(rrc_type, list(uesim_rrc_mapping.keys()))
        return uesim_rrc_mapping[rrc_type]

    def _remove_prefix(self, mapping_name, exclusions):
        for ex in exclusions:
            if ex in mapping_name:
                return mapping_name
        return re.sub(r'\w+-', '', mapping_name, 1)

    def _change_order(self, mapping_name, applied_only_for):
        for apply in applied_only_for:
            if apply in mapping_name:
                split = mapping_name.split('-')
                new = [split[1], split[0]]
                new.extend(split[2:])  # reverse first 2 words)
                return "-".join(new)
        return mapping_name

    def _change_order_last_two_words(self, mapping_name, applied_only_for):
        for apply in applied_only_for:
            if apply in mapping_name:
                split = mapping_name.split('-')
                new = [split[-1], split[-2]]
                new_name = split[:-2]
                new_name.extend(new)  # reverse last 2 words
                return "-".join(new_name)
        return mapping_name

    def get_converted_msgs_list(self, file_or_string):
        """
        Returns list of Message objects.
        :param file_or_string: must be a finite source e.g. file or string, not a process.
        :return:
        """
        return [msg for msg in self.iter_parsed_msg(file_or_string)]

    def get_unparsed_msgs_list(self, file_or_string):
        """
        Returns list of data records as namedtuples.
        :param file_or_string: must be a finite source e.g. file or string, not a process.
        :return:
        """
        return [msg for msg in self.iter_unparsed_msg(file_or_string)]

    def iter_unparsed_msg(self, source):
        """
        Generator that return data record implemented as namedtuples in HexSourceDescription class.
        :param source: either string or file-like objects implementing read(size)
        :return: namedtuple with mandatory fields: hex, type
        """
        for packet in self.iter_packets(source):
            for data_record in self.get_hex_message_and_type_list(packet):
                yield data_record

    def iter_parsed_msg(self, source):
        """
        Generator that returns parsed messages.
        :param source:
        :return:
        """
        for unprased_msg in self.iter_unparsed_msg(source):
            yield self.get_parsed_msg(unprased_msg)

    def iter_packets(self, hex_source):
        """
        Generator that returns single packets (single line with all required columns declared in tshark.
        :param hex_source:
        :return: single tshark line with all declared columns
        """
        file_like_data_source = self.unify_read_api(hex_source)
        remaining = ""
        for chunk in self.iter_chunk(file_like_data_source):
            remaining = "".join([remaining, chunk])
            unparsed_part_index = 0
            for match in re.finditer(self.source_description.source_template, remaining):
                unparsed_part_index = match.end()
                yield match.group(1)
            remaining = remaining[unparsed_part_index:]

    def iter_chunk(self, file_like_data_source, chunk_size=4096):
        """
        Generator that returns chunks (portion of data from source, can be e.g. a part of single tshark line.
        :param file_like_data_source:
        :param chunk_size:
        :return:
        """
        assert chunk_size > 0
        return self._iter_chunk(file_like_data_source, chunk_size=chunk_size)

    def _iter_chunk(self, data_source, chunk_size=4096):
        while self.stop_condition():
            chunk = data_source.read(chunk_size)
            if not chunk:
                if self.stop_condition() != self._default_stop_condition():
                    time.sleep(self._sleep_between_chunks)
                    continue
                else:
                    break
            yield self._apply_substitutions_for_output(chunk)

    def _apply_substitutions_for_output(self, chunk):
        for (sub_from, sub_to) in self.source_output_substitutes:
            chunk = re.sub(sub_from, sub_to, chunk)
        return chunk

    def unify_read_api(self, file_or_string_data_source):
        """
        Reading either from string or from file-like objects implementing read(size). Implemented to support some post-processing of log file.
        :param file_or_string_data_source:
        :return:
        """
        if isinstance(file_or_string_data_source, basestring):
            string_data_source = file_or_string_data_source
            file_like_data_source = StringIO(string_data_source)
        else:
            file_like_data_source = file_or_string_data_source
        assert hasattr(file_like_data_source, "read")
        return file_like_data_source

    def _get_message_type_from_hex_and_pdu_type(self, rrc_type, msg_hex, pdu_type):
        """
        Tries to resolve message name in static mapping based on generic message type (e.g. DL-CCCH-Message) and message hex value.
        Error means lack of implementation of given message type.
        :param rrc_type:
        :param msg_hex:
        :param pdu_type:
        :return:
        """
        msg_hex = self._fix_payloads_for_specific_pdu_types(if_fix_payload=USE_PAYLOAD_FIX, pdu_type=pdu_type, payload=msg_hex, rrc_type=rrc_type)
        try:
            [msg_type, uesim_type] = protocol_mapping[rrc_type][pdu_type](msg_hex)
            # print(msg_type, uesim_type)
            if isinstance(msg_type, list):      # in case single hex message carries many message types, as for SIB2..SIB5 in 5G
                return zip(msg_type, [uesim_type] * len(msg_type))
            else:
                return [(msg_type, uesim_type)]
        except Exception as e:
            error_text = 'Cannot get msg type for {}:{}, occurred error: {}:{}'.format(msg_hex, pdu_type, e.__class__.__name__, e)
            if RAISE_ON_MSG_TYPE_DECODE_FAILED:
                raise Exception(error_text)
            else:
                logger.error(error_text)
                return None, None

    def get_hex_message_and_type_list(self, hex_line):
        """
        Based on single tshark line with all columns and supplied HexSourceDescription, returns single data record (namedtuple).
        In data record the .type attribute is resolved message name (e.g. MobilityFromEUTRACommand). In data record
        all columns declared in HexSourceDescription are available.
        :param hex_line: e.g.
        :return:
        """
        hex_line = str(hex_line)
        hex_line_field_values = re.split(self.source_description.source_separator, hex_line)
        hex_value_index = self.source_description.source_column_descriptions.index('hex')
        hex_value = hex_line_field_values[hex_value_index]
        rrc_type = self._extract_and_set_rrc_type_from_source_description(hex_line_field_values)
        index_of_message_type = self.source_description.source_column_descriptions.index('type')
        message_type_hex = hex_line_field_values[index_of_message_type]
        uesim_message_type = self._convert_hex_message_type_to_uesim_message_type(message_type_hex)
        list_of_msg_types_and_uesim_types = self._get_message_type_from_hex_and_pdu_type(rrc_type,
                                                                                         hex_value,
                                                                                         uesim_message_type)
        # print(list_of_msg_types_and_uesim_types)        # [('msg1', 'uesim1'), ('msg2', 'uesim1')]
        for (msg_type, corrected_uesim_type) in list_of_msg_types_and_uesim_types:
            uesim_message_type = corrected_uesim_type if corrected_uesim_type is not None else uesim_message_type
            hex_line_field_values[index_of_message_type] = msg_type
            if msg_type:
                yield self.source_description.get_data_record(hex_line_field_values + [uesim_message_type])

    def _extract_and_set_rrc_type_from_source_description(self, hex_line_field_values):
        if 'protocol' in self.source_description.source_column_descriptions:
            rrc_type_hex = hex_line_field_values[self.source_description.source_column_descriptions.index('protocol')]
            if FORCED_PROTOCOL is not None and FORCED_PROTOCOL in list(rrc_type_mapping.values()):
                rrc_type = FORCED_PROTOCOL
            else:
                rrc_type = self._covert_hex_rrc_type_to_named_rrc_type(rrc_type_hex)
            hex_line_field_values[self.source_description.source_column_descriptions.index('protocol')] = rrc_type
        else:
            rrc_type = 'rrc'
        return rrc_type

    def _covert_hex_rrc_type_to_named_rrc_type(self, hex_rrc_type):
        """
        Converts hex type to one of ['rrc', 'nr-rrc']
        :param hex_rrc_type:
        """
        hex_rrc_type = re.sub('0x0+', '0x', hex_rrc_type)
        return rrc_type_mapping[hex_rrc_type]

    def _convert_hex_message_type_to_uesim_message_type(self, hex_message_type):
        """
        Converts e.g. 0x0028 value to e.g. DL_MCCH
        :param hex_message_type:
        :return:
        """
        hex_message_type = str(hex_message_type)
        hex_message_type = re.sub('0x', '', hex_message_type)
        return self.message_type_mapping[int(hex_message_type, 16)]

    def get_parsed_msg(self, data_record_object):
        """
        Based on data record decodes message from hex using uesim-dump and converts it to Message object.
        All additional params beyond hex and type values are accessible in meta_data of Message object and
        can be retrieved as the object attributes (e.g. my_msg.my_meta).
        :param data_record_object:
        :return: Message object
        """
        uesimhexmsg_object = self._create_uesim_hex_msgs(data_record_object)
        asn_value_msg = self._convert_uesim_hex_msg2asn_value(uesimhexmsg_object.dump_for_uesim())
        asn_python_struct = ConvertAsnToPythonStructure(asn_value_msg).get()[0]
        meta_data = data_record_object._asdict()
        for meta_key in list(meta_data.keys()):
            if meta_key not in self.source_description.source_column_descriptions:
                del meta_data[meta_key]
        msg = Message(asn_python_struct, meta_data)
        return msg

    def _create_uesim_hex_msgs(self, source_record):
        """
        Creates uesim object that can be parserd with @dump command. Uses internal uesim_type type value stored in
        record field, that must be implemented for uesim-dump-like UesimHexSourceDescription.
        :param source_record:
        :return:
        """
        (pdu_type, payload) = source_record.uesim_type, source_record.hex
        if 'protocol' in source_record._fields:
            rrc_type = source_record.protocol
        else:
            rrc_type = 'rrc'
        payload = self._fix_payloads_for_specific_pdu_types(USE_PAYLOAD_FIX, pdu_type, payload, rrc_type)
        uesim_protocol = self._convert_rrc_type_to_uesim_rrc_type(rrc_type)
        return UesimParser.UesimHexMsg(uesim_protocol, pdu_type, payload)

    def _fix_payloads_for_specific_pdu_types(self, if_fix_payload, pdu_type, payload, rrc_type):
        """
        Cuts off 2 first bytes of DL-DCCH and UL-DCCH message types as workaround for JIRA:
        https://jira3.int.net.nokia.com/browse/IPHY-3531
        :param pdu_type:    uesim-mapped pdu_type
        :param payload:
        :return:
        """
        if if_fix_payload:
            need_payload_fix = ['DL-DCCH-Message', 'UL-DCCH-Message']
            if pdu_type in need_payload_fix:
                if rrc_type == 'rrc':
                    # cut off 2 first hex symbols / 1 byte
                    return payload[2:]
                else:
                    # cut off 4 first hex symbols / 2 bytes
                    return payload[4:]
            else:
                # for rest msg_typed do nothing
                return payload
        else:
            return payload

    def _execute_uesim_process(self, uesim_hex_msg):
        p1 = subprocess.Popen(['/bin/echo', uesim_hex_msg], stdout=subprocess.PIPE)
        try:
            p2 = subprocess.Popen([self.uesim_dump_path], stdin=p1.stdout, stdout=subprocess.PIPE)
        except OSError as exc:
            if 'No such file or directory' in str(exc):
                print(
                    '\n\n###\nUesim-dump is not found. You can set path in environment variable '
                    '"UESIM_DUMP_PATH" if location is different then: /opt/emssim/util/uesim-dump\n###\n\n')
            raise
        p1.stdout.close()
        return p2.stdout.read().decode()

    def _convert_uesim_hex_msg2asn_value(self, uesim_hex_msg):
        HEXED_BYTE_LEN = 2
        command_output = self._execute_uesim_process(uesim_hex_msg)
        if command_output.find("!!! syntax") != -1:
            raise UesimConverterError("Uesim-dump syntax error, msg: %s " % uesim_hex_msg)
        elif re.search(r"error: excessive (\d+) bytes or garbled PDU", command_output):
            cut_bytes = int(re.search(r"error: excessive (\d+) bytes or garbled PDU", command_output).group(1)) * HEXED_BYTE_LEN
            return self._convert_uesim_hex_msg2asn_value(uesim_hex_msg[:-cut_bytes])
        elif re.search(r"error: decoded \d+ bytes, out of \d+ \((\d+) left\)", command_output):
            cut_bytes = int(
                re.search(r"error: decoded \d+ bytes, out of \d+ \((\d+) left\)", command_output).group(1)) * HEXED_BYTE_LEN
            return self._convert_uesim_hex_msg2asn_value(uesim_hex_msg[:-cut_bytes])
        elif command_output.find("value") != -1:
            return command_output
        else:
            raise UesimConverterError("Uesim-dump msg: %s\n command output '%s'\n" % (uesim_hex_msg, command_output))

    def _convert_asn_value2pythons_structure(self, asn_value_msg):
        try:
            return ConvertAsnToPythonStructure(asn_value_msg).get()[0]
        except IndexError:
            raise AsnParserError('Asn value message has not been decoded')

    def parse_container(self, protocol, information_element, hex_to_be_parsed):
        """
        :param protocol: e.g. rrc, s1ap, x2ap, m3ap, nas, 1x, hrpd
        :param information_element: expected to be stored inside container
        :param hex_to_be_parsed: hex to be parsed
        :return: MessageField encapsulating parsed rrc container
        """
        protocol = str(protocol).lower()
        assert protocol in self.uesim_dump_supported_protocols, \
            "Protocol {} not supported by uesim-dump, allowed protocols {}".format(protocol, self.uesim_dump_supported_protocols)
        hex_to_be_parsed = re.sub(r'0x', '', hex_to_be_parsed)
        uesim_hex = UesimParser.UesimHexMsg(protocol, information_element, hex_to_be_parsed).dump_for_uesim()
        asn1_pdu = self._convert_uesim_hex_msg2asn_value(uesim_hex)
        return MessageField(self._convert_asn_value2pythons_structure(asn1_pdu))
